import logging
import os
import sys
from importlib import import_module

import click
from lazy_group import LazyGroup


class DeferredCluster(LazyGroup):
    # Subcommands are resolved to modules only when the user selects them
    def __init__(self, *args, lazy_subcommands=None, **kwargs):
        super().__init__(*args, **kwargs)
        self.lazy_subcommands = lazy_subcommands or {}

    def list_commands(self, ctx):
        return sorted(self.lazy_subcommands)

    def get_command(self, ctx, name):
        if name in self.lazy_subcommands:
            module_path = self.lazy_subcommands.get(name)
            if module_path is None:
                return None
            logging.debug("Importing %s on demand", module_path)
            mod = import_module(module_path)
            return getattr(mod, "cli")
        return super().get_command(ctx, name)


@click.group(
    cls=DeferredCluster,
    lazy_subcommands={"ingest": "pipeline.ingest.cli", "report": "pipeline.report.cli"},
    help="Main command for the lazy example",
)
def app():
    pass


def main(argv):
    logging.basicConfig(level=logging.DEBUG)
    try:
        app.main(args=argv, prog_name=os.path.basename(sys.argv[0]))
    except SystemExit as exc:
        return int(exc.code or 0)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

